pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DepositLog} from "../src/DepositLog.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DepositLog c;

    function setUp() public {
        c = new DepositLog();
    }

    function _check(address _caller) internal {
        vm.assume(!c.approvedLoggers(_caller));
        assertTrue(c.approvedToLog(_caller) == c.approvedLoggers(_caller));
    }

    function testFuzz_check(address _caller) public {
        vm.assume(_caller.code.length == 0 && uint160(_caller) > 0xffff && _caller != address(this) && _caller != address(c) && _caller != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && _caller != 0x000000000000000000636F6e736F6c652e6c6f67 && _caller != 0x4e59b44847b379578588920cA78FbF26c0B4956C && _caller != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _check(_caller);
    }

    receive() external payable {}

    fallback() external payable {}
}
